export const RecorderScreen = () => {
  const playAudio = () => {
    const audio = new Audio(loadAudio());
    audio.play();
  };

  return (
    <Frame>
      <Screen>RecorderScreen</Screen>
      {/* <RecorderCanvas id='recorder_wave' /> */}
      <button onClick={playAudio}></button>
    </Frame>
  );
};
